fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        if maxsplit == 0 {
            // No splitting - just return the original string
            result.push(vec![s]);
        } else {
            // Use rsplitn with maxsplit + 1 to get at most maxsplit splits
            let parts: Vec<String> = s.rsplitn((maxsplit as usize) + 1, &sep)
                .map(|part| part.to_string())
                .collect();
            
            // Reverse the parts since rsplitn returns from right to left
            // but we want to maintain the original order
            let mut reversed_parts: Vec<String> = parts.into_iter().rev().collect();
            
            // Ensure non-empty result (for empty string case)
            if reversed_parts.is_empty() {
                reversed_parts.push("".to_string());
            }
            
            result.push(reversed_parts);
        }
    }
    
    result
}